const input = $('Mattermost Trigger Assistant 1C Sync Bot').first().json;

// В WebSocket-событии Mattermost post часто лежит строкой JSON в data.post
let post = input.post || input.data?.post || input.body?.post || null;

if (typeof post === 'string') {
  try {
    post = JSON.parse(post);
  } catch (e) {
    post = {};
  }
}

post = post || {};

const data = input.data || {};
const broadcast = input.broadcast || {};

const message = (post.message || input.message || '').trim();

const channelId =
  post.channel_id ||
  data.channel_id ||
  broadcast.channel_id ||
  input.channel_id ||
  input.channelId;

const userId =
  post.user_id ||
  data.user_id ||
  broadcast.user_id ||
  input.user_id ||
  input.userId;

const postId =
  post.id ||
  input.post_id ||
  input.postId;

const rootId =
  post.root_id ||
  post.rootId ||
  postId;

const teamId =
  post.team_id ||
  data.team_id ||
  broadcast.team_id ||
  input.team_id ||
  input.teamId ||
  'no-team';

const channelType =
  data.channel_type ||
  input.channel_type ||
  input.channelType;

// ВАЖНО: вставь сюда user_id бота из Mattermost
const BOT_USER_ID = 'ahy7p1cegbdk88awn6g4xiiorr';

// Отсекаем пустые сообщения
if (!message) {
  return [];
}

// Отсекаем сообщения самого бота, чтобы не было бесконечного цикла
if (userId === BOT_USER_ID) {
  return [];
}

// Нас интересуют именно личные сообщения пользователю-боту.
// В Mattermost direct channel обычно имеет тип D.
const isDirectMessage = channelType === 'D';

// Если хочешь реагировать только на личные сообщения боту — оставь так:
if (!isDirectMessage) {
  return [];
}

return [
  {
    json: {
      source: 'mattermost',
      event: input.event || 'posted',
      message,
      originalMessage: message,
      postId,
      rootId,
      channelId,
      channelType,
      teamId,
      userId,
      sessionId: `mm:${teamId}:${channelId}:${userId}`,
      post,
      raw: input,
    },
  },
];

const inputResult = $("Normalize Mattermost Message").all();
const firstItemJson = inputResult[0].json.post;
const timestamp = firstItemJson.create_at;
const date = new Date(timestamp);
const full_date = date.toISOString();

return [{ json: { time_data: full_date } }];

// Запрос из 1С (унифицированная форма-чат).
// Поддерживаем несколько вариантов имён полей.
const b = $json.body || {};

const message = String(b.chatInput ?? b.message ?? b.question ?? '').trim();
const userLogin = String(b.userLogin ?? b.user ?? b.username ?? b.login ?? '').trim();

if (!message) {
  throw new Error('Пустое сообщение: ожидается поле chatInput');
}
if (!userLogin) {
  throw new Error('Не передана доменная учётная запись: ожидается поле userLogin');
}

const requestId = String(b.requestId ?? b.request_id ?? `1c-${$execution.id}`);

return [
  {
    json: {
      source: '1c',
      message,
      requestId,
      requestDt: b.requestDt || new Date().toISOString(),
      sessionId: String(b.sessionId ?? b.session_id ?? requestId),
      userLogin,              // DOMAIN\Login, одинарный обратный слеш
      userName: userLogin,
      channelId: null,
      rootId: null,
    },
  },
];

// Общий контекст для обеих точек входа (Mattermost и 1С)
const fromMM = $('Normalize Mattermost Message').isExecuted;

let ctx;

if (fromMM) {
  const n = $('Normalize Mattermost Message').first().json;
  const d = $('Code in JavaScript Get Date').first().json;
  ctx = {
    source: 'mattermost',
    message: n.message,
    requestId: n.postId,
    requestDt: d.time_data,
    sessionId: n.sessionId,
    userLogin: $json.username,
    userName: n.raw?.data?.sender_name || '',
    channelId: n.channelId,
    rootId: n.rootId,
  };
} else {
  ctx = { ...$json };
}

return [{ json: ctx }];

